changeSet.sql:
ALTER TABLE job
ADD CONSTRAINT chk_job_risk
CHECK ( risk IN ('LOW', 'MEDIUM', 'HIGH', 'VERY_HIGH'));

UPDATE job SET risk = '1' WHERE risk = 'LOW';
UPDATE job SET risk = '2' WHERE risk = 'MEDIUM';
UPDATE job SET risk = '3' WHERE risk = 'HIGH';
UPDATE job SET risk = '4' WHERE risk = 'VERY_HIGH';
